-- c016-v001: И прошедшей – субботе – Мария – Магдалина и Мария – – Иакова и Саломия купили ароматы чтобы придя помазать Его
-- c016-v002: И очень рано–утром в– первый – день–недели приходят к– – гробнице взошедшем – солнце
-- c016-v003: И говорили между– собой Кто отвалит нам – камень от– – двери – гробницы
-- c016-v004: И взглянув видят что отвален – камень был ибо великий весьма
-- c016-v005: И войдя в– – гробницу увидели юношу сидящего по– – правую–сторону облечённого в–одежду белую и ужаснулись
-- c016-v006: – же говорит им Не– ужасайтесь Иисуса ищете – Назарянина – Распятого Воскрес не– есть здесь вот – место где положили Его
-- c016-v007: Но идите скажите – ученикам Его и – Петру что Идёт–прежде вас в– – Галилею там Его увидите как сказал вам
-- c016-v008: И выйдя убежали от– – гробницы имело ибо их трепет и ужас и никому ничего сказали боялись ибо
-- c016-v009: Воскреснув же рано–утром первого–дня недели явился сначала Марии – Магдалине от– которой изгнал семь бесов
-- c016-v010: Она пойдя возвестила – с– Ним бывшим скорбящим и плачущим
-- c016-v011: И–они услышав что живёт и был–виден – ею не–поверили
-- c016-v012: После же этого двоим из– них идущим явился в– другом облике идущим в– сельскую–местность
-- c016-v013: И–они ушедшие возвестили – остальным и–не тем поверили
-- c016-v014: Позже же возлежащим им – одиннадцати явился и упрекал – неверие их и жестокосердие что – видевшим Его воскресшего из– мёртвых не– поверили
-- c016-v015: И сказал им Шедшие в– – мир весь проповедуйте – Евангелие всей – твари
-- c016-v016: – Поверивший и крестившийся спасётся – же не–поверивший осудится
-- c016-v017: Знамения же – поверившим сии будут–сопровождать в– – имени Моём бесов будут–изгонять языками будут–говорить новыми
-- c016-v018: и в– – руках змей будут–брать и–если смертоносное что–либо выпьют не– никак им повредит на– больных руки возложат и хорошо будут–иметь
-- c016-v019: – итак же Господь Иисус после– – говорения им был–вознесён на– – небо и сел по– правую–сторону – Бога
-- c016-v020: Они же выйдя проповедовали повсюду – Господа содействующего и – слово подтверждающего через– – сопровождающих знамений Всё же – повеленное – вокруг– – Петра кратко возвестили после же этого и Сам – Иисус от– востока и до– запада разослал через– них – священную и нетленную проповедь – вечного спасения Аминь

